import { reexportRenderer } from "@astrojs/internal-helpers/renderer";
import { getContainerRenderer as getRendererPackageContainerRenderer, getRenderer as getRendererPackageRenderer } from "@astrojs/react-renderer/container-renderer";
const fromRendererPackage = (renderer) => reexportRenderer(renderer, "@astrojs/react-renderer", "@astrojs/react");
export function getRenderer(...args) {
	return fromRendererPackage(getRendererPackageRenderer(...args));
}
export function getContainerRenderer() {
	return fromRendererPackage(getRendererPackageContainerRenderer());
}
